using DSWI_T1_1.Data;using DSWI_T1_1.Models;using DSWI_T1_1.Repositories.Interfaces;using Microsoft.EntityFrameworkCore;using Microsoft.Data.SqlClient;using System.Data;namespace DSWI_T1_1.Repositories.Implementations;public class CitaRepository:ICitaRepository{private readonly ClinicaDbContext db;public CitaRepository(ClinicaDbContext c)=>db=c;public async Task<IReadOnlyList<Cita>> ObtenerTodosAsync()=>await db.Citas.FromSqlRaw("EXEC dbo.usp_Citas_Listar").AsNoTracking().ToListAsync();public async Task<Cita?> ObtenerPorIdAsync(int id){var lista=await db.Citas.FromSqlInterpolated($"EXEC dbo.usp_Citas_ObtenerPorId @CitaID={id}").AsNoTracking().ToListAsync();return lista.FirstOrDefault();}public async Task<int> CrearAsync(Cita c){var id=new SqlParameter("@NuevoID",SqlDbType.Int){Direction=ParameterDirection.Output};await db.Database.ExecuteSqlInterpolatedAsync($"EXEC dbo.usp_Citas_Crear @Fecha={c.Fecha},@Hora={c.Hora},@Especialidad={c.Especialidad},@Estado={c.Estado},@PacienteID={c.PacienteID},@NuevoID={id} OUTPUT");return id.Value==DBNull.Value?0:(int)id.Value;}public async Task<bool> EditarAsync(Cita c){await db.Database.ExecuteSqlInterpolatedAsync($"EXEC dbo.usp_Citas_Editar @CitaID={c.CitaID},@Fecha={c.Fecha},@Hora={c.Hora},@Especialidad={c.Especialidad},@Estado={c.Estado},@PacienteID={c.PacienteID}");return true;}}